1: namespace QBrainAi.Support.Mcp.Tests.Configuration;
2: 
3: /// <summary>
4: /// TR-MCP-USECASE-018 (AC-006), TR-MCP-USECASE-019 (AC-008): binds <see cref="UnitSuitePlatformScanner"/>,
5: /// unchanged from its mock gate, to the C# sources of every project the Nuke <c>Test</c> target runs
6: /// (<c>build/Build.Test.cs</c>: test projects except integration, plugin-integration, review and Build.Tests
7: /// projects). A test that depends on the platform is an integration test, so the unit test classes hold
8: /// no operating-system check, OS-platform attribute, xUnit skip, or real process-host binding.
9: /// </summary>
10: public sealed class UnitSuitePlatformScannerTests
11: {
12:     private static readonly string[] ExpectedUnitProjects =
13:     [
14:         "QBrainAi.Client.Tests",
15:         "QBrainAi.Cqrs.Tests",
16:         "QBrainAi.Launcher.Tests",
17:         "QBrainAi.McpAgent.Tests",
18:         "QBrainAi.QBAgent.Tests",
19:         "QBrainAi.Repl.Core.Tests",
20:         "QBrainAi.Support.Mcp.Tests",
21:     ];
22: 
23:     /// <summary>No unit test class in the unit-suite projects depends on the platform.</summary>
24:     [Fact]
25:     public void UnitTestClasses_HaveNoPlatformDependence()
26:     {
27:         var testsRoot = FindTestsRoot();
28:         var findings = UnitProjects(testsRoot)
29:             .SelectMany(project => Directory.EnumerateFiles(project, "*.cs", SearchOption.AllDirectories))
30:             .Where(path => !IsBuildOutput(path))
31:             .OrderBy(path => path, StringComparer.Ordinal)
32:             .SelectMany(path => UnitSuitePlatformScanner.Scan(
33:                 Path.GetRelativePath(testsRoot, path).Replace('\\', '/'),
34:                 File.ReadAllText(path)))
35:             .Select(finding => finding.ToString())
36:             .ToArray();
37: 
38:         Assert.True(
39:             findings.Length == 0,
40:             "A test that depends on the platform is an integration test: tag its class [Trait(\"Category\", \"Integration\")] "
41:             + "(with [Trait(\"Platform\", ...)] when it applies to one host) or remove the dependence. Findings:"
42:             + Environment.NewLine + string.Join(Environment.NewLine, findings));
43:     }
44: 
45:     /// <summary>
46:     /// Pins the projects the guard scans to the seven the Nuke <c>Test</c> target ran when this was written
47:     /// (<c>build/Build.Test.cs:16-24</c>): a test project added to or removed from <c>tests/</c> changes the
48:     /// guard's selection and fails here. Limit: this test does not read <c>build/Build.Test.cs</c>, so a
49:     /// change confined to that target's selection leaves it green and must be mirrored here by hand.
50:     /// </summary>
51:     [Fact]
52:     public void GuardProjectSelection_MatchesTheUnitTestTarget()
53:     {
54:         var names = UnitProjects(FindTestsRoot()).Select(directory => new DirectoryInfo(directory).Name).Order(StringComparer.Ordinal).ToArray();
55:         Assert.Equal(ExpectedUnitProjects, names);
56:     }
57: 
58:     private static IEnumerable<string> UnitProjects(string testsRoot) =>
59:         Directory.EnumerateDirectories(testsRoot)
60:             .Where(directory =>
61:             {
62:                 var name = new DirectoryInfo(directory).Name;
63:                 return name.EndsWith(".Tests", StringComparison.Ordinal)
64:                     && !name.Contains("IntegrationTests", StringComparison.Ordinal)
65:                     && !name.Contains("PluginIntegration", StringComparison.Ordinal)
66:                     && !name.Contains("Review.Tests", StringComparison.Ordinal)
67:                     && !name.EndsWith("Build.Tests", StringComparison.Ordinal)
68:                     && Directory.EnumerateFiles(directory, "*.csproj").Any();
69:             });
70: 
71:     private static bool IsBuildOutput(string path)
72:     {
73:         var separator = Path.DirectorySeparatorChar;
74:         return path.Contains($"{separator}bin{separator}", StringComparison.OrdinalIgnoreCase)
75:             || path.Contains($"{separator}obj{separator}", StringComparison.OrdinalIgnoreCase);
76:     }
77: 
78:     private static string FindTestsRoot()
79:     {
80:         for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
81:         {
82:             if (File.Exists(Path.Combine(directory.FullName, "QBrainAi.sln")))
83:                 return Path.Combine(directory.FullName, "tests");
84:         }
85: 
86:         throw new DirectoryNotFoundException($"Could not locate the repository root from '{AppContext.BaseDirectory}'.");
87:     }
88: }

