File=tests/QBrainAi.Support.Mcp.Tests/Configuration/UnitSuitePlatformScanner.cs
1: using System.Text;
2: using System.Text.RegularExpressions;
3: 
4: namespace QBrainAi.Support.Mcp.Tests.Configuration;
5: 
6: /// <summary>
7: /// TR-MCP-USECASE-018 (AC-006), TR-MCP-USECASE-019 (AC-008): finds platform dependence in unit test classes.
8: /// A test that depends on the platform is an integration test (operator 2026-10-19: "If it depends on the
9: /// environment, it's an integration test."), so an operating-system check, an OS-platform attribute, an
10: /// xUnit skip, or a binding to the real process host is a finding unless its test class (or an enclosing
11: /// class) carries <c>[Trait("Category", "Integration")]</c>. Strings and comments are ignored, but the code
12: /// inside an interpolation hole is not. Test classes are types whose name ends in <c>Tests</c> or that
13: /// declare <c>[Fact]</c> or <c>[Theory]</c> methods; other helper types (for example the host-neutral
14: /// <c>UnitTestPaths</c> fixture) are not test classes. The scan reads source text only: dependence reached
15: /// through a helper type, or through operating-system behavior of a base-library call such as
16: /// <c>Path.GetFullPath</c>, is outside it.
17: /// </summary>
18: internal static class UnitSuitePlatformScanner
19: {
20:     /// <summary>Skip calls and skippable attributes, which never span lines (declared before <see cref="Rules"/>, which uses it).</summary>
21:     private static readonly Regex SkipCall = new(
22:         @"\bAssert\s*\.\s*Skip(?:When|Unless)?\b|\bSkipException\b|\bSkippable(?:Fact|Theory)\b",
23:         RegexOptions.CultureInvariant);
24: 
25:     private static readonly (string Kind, Regex Pattern)[] Rules =
26:     [
27:         ("os-check", new Regex(@"\bOperatingSystem\s*\.\s*Is[A-Z]\w*\s*\(", RegexOptions.CultureInvariant)),
28:         ("os-check", new Regex(@"\bRuntimeInformation\s*\.\s*IsOSPlatform\s*\(", RegexOptions.CultureInvariant)),
29:         ("os-attribute", new Regex(@"\[\s*(?:[\w.]+\.)?(?:Supported|Unsupported)OSPlatform(?:Attribute)?\s*\(", RegexOptions.CultureInvariant)),
30:         ("skip", SkipCall),
31:         ("process-host", new Regex(@"\bSystemWorkspaceHostEnvironment\s*\.\s*Instance\b|\bWorkspacePathNormalizer\s*\.\s*Process\b", RegexOptions.CultureInvariant)),
32:     ];
33: 
34:     private static readonly Regex TypeDeclaration = new(
35:         @"\b(?:class|record|struct|interface)\s+([A-Za-z_]\w*)",
36:         RegexOptions.CultureInvariant);
37: 
38:     private static readonly Regex IntegrationTrait = new(
39:         @"\[\s*(?:Xunit\.)?Trait(?:Attribute)?\s*\(\s*""Category""\s*,\s*""Integration""\s*\)",
40:         RegexOptions.CultureInvariant);
41: 
42:     private static readonly Regex TestAttribute = new(
43:         @"(?<=[\[,]\s*)(?:global\s*::\s*)?(?:[A-Za-z_]\w*\s*\.\s*)*(?:Fact|Theory)(?:Attribute)?\b",
44:         RegexOptions.CultureInvariant);
45: 
46:     /// <summary>A <c>[Fact(</c> or <c>[Theory(</c> argument list, plain, qualified, or later in an attribute list.</summary>
47:     private static readonly Regex TestAttributeCall = new(
48:         @"(?<=[\[,]\s*)(?:global\s*::\s*)?(?:[A-Za-z_]\w*\s*\.\s*)*(?:Fact|Theory)(?:Attribute)?\s*\(",
49:         RegexOptions.CultureInvariant);
50: 
51:     /// <summary>The xUnit skip properties: <c>Skip</c>, <c>SkipUnless</c>, <c>SkipWhen</c>, <c>SkipType</c>.</summary>
52:     private static readonly Regex SkipArgument = new(@"\bSkip\w*\s*=(?!=)", RegexOptions.CultureInvariant);
53: 
54:     /// <summary>
55:     /// TR-MCP-USECASE-018 (AC-006): the one definition of an xUnit skip shared by this scanner and the skip
56:     /// guard. Returns the 1-based lines of code (already stripped of strings and comments) that hold a skip
57:     /// call, <c>SkipException</c>, a skippable attribute, or a test attribute whose argument list (which may
58:     /// span lines) sets a skip property; an attribute is reported on the line of its name.
59:     /// </summary>
60:     /// <param name="strippedCode">Output of <see cref="StripCommentsAndStrings"/>.</param>
61:     internal static IReadOnlyList<int> FindSkipLines(string strippedCode)
62:     {
63:         ArgumentNullException.ThrowIfNull(strippedCode);
64:         var code = strippedCode.Replace("\r\n", "\n", StringComparison.Ordinal);
65:         var lines = new SortedSet<int>();
66:         foreach (Match call in SkipCall.Matches(code))
67:             lines.Add(LineOf(code, call.Index));
68:         foreach (Match attribute in TestAttributeCall.Matches(code))
69:         {
70:             var open = attribute.Index + attribute.Length - 1;
71:             var close = MatchingParenthesis(code, open);
72:             var arguments = code.Substring(open + 1, (close < 0 ? code.Length : close) - open - 1);
73:             if (SkipArgument.IsMatch(arguments))
74:                 lines.Add(LineOf(code, attribute.Index));
75:         }
76: 
77:         return lines.ToArray();
78:     }
79: 
80:     /// <summary>Scans one C# source file and returns its findings in line order.</summary>
81:     /// <param name="relativePath">Path reported with each finding.</param>
82:     /// <param name="source">File text.</param>
83:     internal static IReadOnlyList<UnitSuitePlatformFinding> Scan(string relativePath, string source)
84:     {
85:         ArgumentNullException.ThrowIfNull(relativePath);
86:         ArgumentNullException.ThrowIfNull(source);
87:         var original = source.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');
88:         var stripped = StripCommentsAndStrings(source).Replace("\r\n", "\n", StringComparison.Ordinal);
89:         var code = stripped.Split('\n');
90:         var skipLines = new HashSet<int>(FindSkipLines(stripped));
91: 
92:         var open = new Stack<TypeScope>();
93:         var hits = new List<(int Line, string Kind, TypeScope? Owner)>();
94:         var attributeHits = new List<(int Line, string Kind)>();
95:         TypeScope? pending = null;
96:         var depth = 0;
97: 
98:         for (var i = 0; i < code.Length; i++)
99:         {
100:             var line = code[i];
101:             var trimmed = line.Trim();
102:             var declaration = TypeDeclaration.Match(line);
103:             if (declaration.Success)
104:             {
105:                 pending = new TypeScope(
106:                     declaration.Groups[1].Value,
107:                     HasIntegrationTrait(original, code, i),
108:                     open.Count > 0 ? open.Peek() : null,
109:                     depth);
110:             }
111: 
112:             if (open.Count > 0 && TestAttribute.IsMatch(line))
113:                 open.Peek().HasTests = true;
114: 
115:             var lineNumber = i + 1;
116:             var lineHits = Rules
117:                 .Where(rule => rule.Kind == "skip" ? skipLines.Contains(lineNumber) : rule.Pattern.IsMatch(line))
118:                 .Select(rule => rule.Kind)
119:                 .ToList();
120:             if (!declaration.Success && trimmed.StartsWith('['))
121:             {
122:                 // Attribute lines belong to the type or member declared after them.
123:                 attributeHits.AddRange(lineHits.Select(kind => (i + 1, kind)));
124:             }
125:             else
126:             {
