396: +    internal static Dictionary<string, string> ParseEnvFile(string text)
397: +    {
398: +        var values = new Dictionary<string, string>(StringComparer.Ordinal);
399: +        foreach (var raw in text.Split('\n'))
400: +        {
401: +            var line = raw.Trim();
402: +            if (line.Length == 0 || line.StartsWith('#'))
403: +            {
404: +                continue;
405: +            }
406: +
407: +            if (line.StartsWith("export ", StringComparison.Ordinal))
408: +            {
409: +                line = line["export ".Length..].TrimStart();
410: +            }
411: +
412: +            var equals = line.IndexOf('=', StringComparison.Ordinal);
413: +            if (equals <= 0)
414: +            {
415: +                continue;
416: +            }
417: +
418: +            var key = line[..equals].Trim();
419: +            var value = line[(equals + 1)..].Trim();
420: +            if (value.Length >= 2 && (value[0] == '"' || value[0] == '\'') && value[^1] == value[0])
