431: +    private static bool TryReadEndpoint(string connectionString, bool isSqlServer, int defaultPort, out string host, out int port, out string problem)
432: +    {
433: +        host = string.Empty;
434: +        port = defaultPort;
435: +        problem = string.Empty;
436: +        var builder = new DbConnectionStringBuilder();
437: +        try
438: +        {
439: +            builder.ConnectionString = connectionString;
440: +        }
441: +        catch (ArgumentException)
442: +        {
443: +            problem = "is not a valid connection string";
444: +            return false;
445: +        }
446: +
447: +        if (isSqlServer)
448: +        {
449: +            var server = FirstValue(builder, "Server", "Data Source", "Address", "Addr", "Network Address");
450: +            if (server is null)
451: +            {
452: +                problem = "names no server";
453: +                return false;
454: +            }
455: +
456: +            if (server.StartsWith("(localdb)", StringComparison.OrdinalIgnoreCase))
457: +            {
458: +                problem = "names a LocalDB server, which has no TCP endpoint on Linux";
459: +                return false;
460: +            }
461: +
462: +            if (server.StartsWith("tcp:", StringComparison.OrdinalIgnoreCase))
463: +            {
464: +                server = server[4..];
465: +            }
466: +
467: +            var comma = server.IndexOf(',', StringComparison.Ordinal);
468: +            if (comma >= 0)
469: +            {
470: +                if (!int.TryParse(server[(comma + 1)..].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out port))
471: +                {
472: +                    problem = "names a server with an unreadable port";
473: +                    return false;
474: +                }
475: +
476: +                server = server[..comma];
477: +            }
478: +
479: +            host = server.Split('\\')[0].Trim();
480: +        }
481: +        else
482: +        {
483: +            var server = FirstValue(builder, "Host", "Server");
484: +            if (server is null)
485: +            {
486: +                problem = "names no host";
487: +                return false;
488: +            }
489: +
490: +            host = server.Split(',')[0].Trim();
491: +            var portText = FirstValue(builder, "Port");
492: +            if (portText is not null && !int.TryParse(portText, NumberStyles.Integer, CultureInfo.InvariantCulture, out port))
493: +            {
494: +                problem = "names an unreadable port";
495: +                return false;
496: +            }
497: +        }
498: +
499: +        if (host.Length == 0 || host == ".")
500: +        {
501: +            host = "localhost";
502: +        }
503: +
504: +        return true;
505: +    }
