507: +    private static string? FirstValue(DbConnectionStringBuilder builder, params string[] keys)
508: +    {
509: +        foreach (var key in keys)
510: +        {
511: +            if (builder.TryGetValue(key, out var value) && value is not null && !string.IsNullOrWhiteSpace(value.ToString()))
512: +            {
513: +                return value.ToString()!.Trim();
514: +            }
515: +        }
516: +
517: +        return null;
518: +    }
