568: +    private static (int ExitCode, string Output) Docker(params string[] arguments)
569: +    {
570: +        var start = new ProcessStartInfo("docker") { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false };
571: +        foreach (var argument in arguments)
572: +        {
573: +            start.ArgumentList.Add(argument);
574: +        }
575: +
576: +        using var process = Process.Start(start) ?? throw new InvalidOperationException("Could not start docker.");
577: +        var output = process.StandardOutput.ReadToEndAsync();
578: +        var error = process.StandardError.ReadToEndAsync();
579: +        if (!process.WaitForExit(TimeSpan.FromMinutes(2)))
580: +        {
581: +            process.Kill(entireProcessTree: true);
582: +            return (-1, string.Empty);
583: +        }
584: +
585: +        _ = error.GetAwaiter().GetResult();
586: +        return (process.ExitCode, output.GetAwaiter().GetResult());
587: +    }
