2243: +/// <summary>
2244: +/// TR-MCP-DB-001: raw-SQL workspace-key assertions for SQLite data-migration tests. A data migration copies the parent
2245: +/// workspace key into every backfilled child row (the child foreign key to Workspaces). EF query parameters compared
2246: +/// with workspace keys are canonicalized by WorkspaceKeyConversion, so a legacy key (for example a backslash Windows
2247: +/// spelling) is only observable through SQL that bypasses EF.
2248: +/// </summary>
2249: +internal static class MigrationKeyAssertions
2250: +{
2251: +    /// <summary>
2252: +    /// Asserts that the only non-global workspace row has exactly <paramref name="expectedKey"/> as its WorkspaceId,
2253: +    /// and that <paramref name="childTable"/> has rows whose WorkspaceId values are all exactly that key.
2254: +    /// </summary>
2255: +    /// <param name="connection">Open connection to the migrated database.</param>
2256: +    /// <param name="childTable">Backfilled child table that carries a WorkspaceId column.</param>
2257: +    /// <param name="expectedKey">The workspace key seeded before the migration, compared ordinally.</param>
2258: +    internal static void AssertChildRowsCarryWorkspaceKey(SqliteConnection connection, string childTable, string expectedKey)
2259: +    {
2260: +        ArgumentNullException.ThrowIfNull(connection);
2261: +        ArgumentException.ThrowIfNullOrWhiteSpace(childTable);
2262: +        ArgumentNullException.ThrowIfNull(expectedKey);
2263: +
2264: +        var parentKeys = ReadStrings(connection, "SELECT \"WorkspaceId\" FROM \"Workspaces\" WHERE \"WorkspaceId\" <> '' ORDER BY 1;");
2265: +        Assert.Equal([expectedKey], parentKeys);
2266: +
2267: +        var childKeys = ReadStrings(connection, $"SELECT DISTINCT \"WorkspaceId\" FROM \"{childTable}\" ORDER BY 1;");
2268: +        Assert.Equal([expectedKey], childKeys);
2269: +    }
2270: +
2271: +    private static List<string> ReadStrings(SqliteConnection connection, string sql)
2272: +    {
2273: +        using var command = connection.CreateCommand();
2274: +        command.CommandText = sql;
2275: +        using var reader = command.ExecuteReader();
2276: +        var values = new List<string>();
2277: +        while (reader.Read())
2278: +        {
2279: +            values.Add(reader.GetString(0));
2280: +        }
2281: +
2282: +        return values;
2283: +    }
