1243: function Invoke-ReplFailsafeDrainOnFirstSuccess {
1244:     <#
1245:     .SYNOPSIS
1246:         TR-MCP-REPL-016: run one queue drain after the first confirmed backend call.
1247:     .DESCRIPTION
1248:         The drain is wired here rather than to bootstrap on purpose. Bootstrap
1249:         (Assert-ReplMarkerFresh) only proves the marker file is fresh, it does not
1250:         prove the backend answers, and it runs inside Invoke-ReplRaw, so draining
1251:         there would recurse. A successful Invoke-ReplRaw is the first point where
1252:         reachability is proven, which is exactly the precondition for replay, and it
1253:         covers every entry path (hooks, workflow verbs, direct client calls) with a
1254:         single hook. Set MCP_FAILSAFE_DRAIN_DISABLED=1 to opt out.
1255:     #>
1256:     [CmdletBinding()]
1257:     param()
1258: 
1259:     if ($script:ReplFailsafeDrainCompleted) { return }
1260:     if ($script:ReplFailsafeDraining) { return }
1261:     if ($env:MCP_FAILSAFE_DRAIN_DISABLED -eq '1') { return }
1262: 
1263:     # TR-MCP-PERSIST-003: do not block getFr/getTr on a nested SubmitAsync drain.
1264:     if ($script:ReplRawInFlight) {
1265:         $script:ReplFailsafeDrainDeferred = $true
1266:         return
1267:     }
1268: 
1269:     Invoke-ReplFailsafeDrainOnFirstSuccessCore
1270: }
