1272: function Invoke-ReplFailsafeDrainOnFirstSuccessCore {
1273:     # TR-MCP-FAILSAFE-001: do not latch completed on a backend-down abort.
1274:     # A 503/backend_unavailable pass must be retryable in this process after
1275:     # storage answers again.
1276:     try {
1277:         $summary = Invoke-ReplFailsafeDrain
1278:         if ($summary.aborted) {
