1280:         }
1281:         $script:ReplFailsafeDrainCompleted = $true
1282:         if ($summary.replayed -gt 0 -or $summary.quarantined -gt 0 -or $summary.failed -gt 0) {
1283:             [Console]::Error.WriteLine(
1284:                 "Failsafe queue drain: replayed=$($summary.replayed) failed=$($summary.failed) quarantined=$($summary.quarantined) skipped=$($summary.skipped) dir='$($summary.failsafeDir)'.")
