1286:     } catch {
1287:         $detail = $_.Exception.Message
1288:         if (Test-ReplFailsafeBackendUnreachable -Detail $detail) {
1289:             return
1290:         }
1291:         [Console]::Error.WriteLine("Failsafe queue drain failed: $detail")
1292:     }
1293: }
