1385: function Get-ReplStableFingerprint {
1386:     # Canonical hash of one logical payload. Timestamps are excluded by the caller.
1387:     param($Value)
1388:     $json = ConvertTo-Json -InputObject $Value -Compress -Depth 20
1389:     $sha = [System.Security.Cryptography.SHA256]::Create()
1390:     try {
1391:         $bytes = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes([string]$json))
1392:         return (([System.BitConverter]::ToString($bytes)) -replace '-', '')
1393:     } finally {
1394:         $sha.Dispose()
1395:     }
1396: }
