File=docs/receipts/hv/hv-ug-r1-persist-verdict.ps1
1: <#
2: .SYNOPSIS
3:     Persists and verifies the complete verdict only in this validator's own session and turn.
4: #>
5: [CmdletBinding(SupportsShouldProcess)]
6: param([ValidateSet('Stage','Append','Complete','Verify')][string]$Mode,[int]$Start = 1,[int]$Count = 5)
7: $ErrorActionPreference = 'Stop'
8: if (-not $PSCmdlet.ShouldProcess('Codex-20261020T005400Z-unitgreen-r1 / req-20261020T005403Z-unitgreen-r1 and own receipts', $Mode)) { return }
9: Import-Module powershell-yaml
10: $sessionId = 'Codex-20261020T005400Z-unitgreen-r1'
11: $requestId = 'req-20261020T005403Z-unitgreen-r1'
12: $mdPath = Join-Path $PSScriptRoot 'hostile-validator-unitgreen-r1-20261019T195131.md'
13: $jsonPath = Join-Path $PSScriptRoot 'hostile-validator-unitgreen-r1-20261019T195131.json'
14: $partsPath = Join-Path $PSScriptRoot 'hv-ug-r1-result-parts.json'
15: $paramsPath = Join-Path $PSScriptRoot ('hv-ug-r1-persist-' + $Mode + '-params.json')
16: function Get-ReviewTextHash {
17:     <#.SYNOPSIS Computes the SHA-256 of exact UTF-8 review text. #>
18:     [CmdletBinding()]
19:     param([string]$Text)
20:     return [Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData([System.Text.Encoding]::UTF8.GetBytes($Text)))
21: }
22: function Invoke-OwnSessionMethod {
23:     <#.SYNOPSIS Invokes a documented method through the installed Codex wrapper and validates its envelope. #>
24:     [CmdletBinding()]
25:     param([string]$Method,[object]$Parameters)
26:     $Parameters | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $paramsPath
27:     $output = & (Join-Path $PSScriptRoot 'hv-ug-r1-session.ps1') -Mode Call -Method $Method -ParamsFile $paramsPath | Out-String
28:     $documents = @(ConvertFrom-Yaml -Yaml $output -AllDocuments)
29:     if (@($documents | Where-Object { $_.type -eq 'error' -or $_.payload.result.persisted -eq $false -or $_.payload.result.queued -eq $true }).Count -gt 0) { throw ('Own session operation failed: ' + $output) }
30:     if ($output -notmatch 'type: result') { throw ('No result envelope: ' + $output) }
31:     return $output
32: }
33: switch ($Mode) {
34:     'Stage' {
35:         $prose = [System.IO.File]::ReadAllText($mdPath)
36:         $json = [System.IO.File]::ReadAllText($jsonPath)
37:         $report = $json | ConvertFrom-Json -Depth 100
38:         if ($report.ClaimCounts.PASS -ne @($report.Claims | Where-Object Verdict -EQ PASS).Count -or $report.ClaimCounts.FAIL -ne @($report.Claims | Where-Object Verdict -EQ FAIL).Count -or $report.ClaimCounts.UNKNOWN -ne @($report.Claims | Where-Object Verdict -EQ UNKNOWN).Count) { throw 'Claim counts differ.' }
39:         if ($report.ReviewerSessionId -ne $sessionId -or $report.ReviewerRequestId -ne $requestId -or $report.ValidatorIdentity.Model -ne 'gpt-6-astra' -or $report.ValidatorIdentity.Effort -ne 'max') { throw 'Identity mismatch.' }
40:         $body = "COMPLETE VERDICT PROSE`n" + $prose + "`nCOMPLETE RECEIPT JSON`n" + $json + "`n=== VERDICT JSON ===`n" + ($report.FinalVerdictJson | ConvertTo-Json -Depth 50 -Compress)
41:         $chunkSize = 12000
42:         $total = [int][Math]::Ceiling($body.Length / [double]$chunkSize)
43:         $parts = for ($index = 0; $index -lt $total; $index++) {
44:             $content = $body.Substring($index * $chunkSize,[Math]::Min($chunkSize,$body.Length - $index * $chunkSize))
45:             [ordered]@{ order = 10000 + $index; timestamp = (Get-Date).ToUniversalTime().ToString('o'); role = 'model'; category = 'observation'; content = ('HV_UNITGREEN_R1_RESULT_PART {0:D3}/{1:D3}' -f ($index + 1),$total) + "`n" + $content }
46:         }
47:         [ordered]@{ PartCount=$total; BodyCharacters=$body.Length; BodySha256=(Get-ReviewTextHash $body); ProseSha256=(Get-ReviewTextHash $prose); JsonSha256=(Get-ReviewTextHash $json); Parts=@($parts) } | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $partsPath
48:         [ordered]@{ TimestampLocal=(Get-Date).ToString('s'); PartCount=$total; BodyCharacters=$body.Length; BodySha256=(Get-ReviewTextHash $body); Claims=12; AllCountsAgree=$true } | ConvertTo-Json
49:     }
50:     'Append' {
51:         $staged = Get-Content -Raw -LiteralPath $partsPath | ConvertFrom-Json -Depth 100
52:         $selected = @($staged.Parts | Select-Object -Skip ($Start - 1) -First $Count)
53:         if ($selected.Count -eq 0) { throw 'No selected parts.' }
54:         $output = Invoke-OwnSessionMethod 'workflow.sessionlog.appendDialog' ([ordered]@{ requestId=$requestId; dialogItems=$selected })
55:         [ordered]@{ TimestampLocal=(Get-Date).ToString('s'); FirstPart=$Start; PartCount=$selected.Count; Persisted=$output -match 'persisted: true'; SessionId=$sessionId; RequestId=$requestId } | ConvertTo-Json
56:     }
57:     'Complete' {
58:         $report = Get-Content -Raw -LiteralPath $jsonPath | ConvertFrom-Json -Depth 100
59:         $prose = [System.IO.File]::ReadAllText($mdPath)
60:         $actions = [System.Collections.Generic.List[object]]::new()
61:         $ordinal = 1
62:         foreach ($finding in $report.Findings) {
